const std=@import("std");
export fn dimensionality_reduction_lda(input:[*c]const f64,n:usize,output:[*c]f64,cap:usize)i64{
 if(input==null or n<16)return -1;const v=input[0..n];if(v[0]!=2 or v[2]!=2 or v[3]!=1 or @floor(v[1])!=v[1] or v[1]<4 or v[1]>8)return -1;const m:usize=@intFromFloat(v[1]);if(n!=4+3*m)return -1;const base=4+2*m;var x:[8]f64=undefined;var y:[8]f64=undefined;var means:[2][2]f64=@splat(@splat(0));var counts:[2]usize=@splat(0);
 for(0..m)|i|{x[i]=v[4+i];y[i]=v[4+m+i];const lab=v[base+i];if(!std.math.isFinite(x[i]) or !std.math.isFinite(y[i]) or @abs(x[i])>10000 or @abs(y[i])>10000 or (lab!=0 and lab!=1))return -1;const c:usize=@intFromFloat(lab);counts[c]+=1;means[c][0]+=x[i];means[c][1]+=y[i];}if(counts[0]<2 or counts[1]<2)return -1;for(0..2)|c|{means[c][0]/=@floatFromInt(counts[c]);means[c][1]/=@floatFromInt(counts[c]);}
 var a:f64=0;var b:f64=0;var d:f64=0;for(0..m)|i|{const c:usize=@intFromFloat(v[base+i]);const dx=x[i]-means[c][0];const dy=y[i]-means[c][1];a+=dx*dx;b+=dx*dy;d+=dy*dy;}a/=@floatFromInt(m);b/=@floatFromInt(m);d/=@floatFromInt(m);const det=a*d-b*b;if(det<=1e-12)return -1;const dx=means[1][0]-means[0][0];const dy=means[1][1]-means[0][1];var w0=(d*dx-b*dy)/det;var w1=(a*dy-b*dx)/det;const norm=@sqrt(w0*w0+w1*w1);if(norm<=1e-12)return -1;w0/=norm;w1/=norm;if(w0<0 or (@abs(w0)<=1e-14 and w1<0)){w0=-w0;w1=-w1;}if(output==null or cap<m)return -2;for(0..m)|i|output[i]=w0*x[i]+w1*y[i];return @intCast(m);
}
